<template>
  <div class="dt-page">

    <div class="charter-list">
      <section v-for="({ key: charterName, value: songList }, index) in sortedCardList" :id="`charter-${index}`" :key="charterName" class="charter-group">
        <div class="dt-section__head">
          <h2 class="charter-title dt-title-bar">{{ charterName }}</h2>
        </div>
        <div class="card-grid" :style="getGridStyle()">
          <div
            v-for="(item, idx) in getGroupSortedCards(songList)"
            :key="idx"
            class="chart-card" @click="openSong(item.songKey)"
          >
            <div class="card-cover">
              <img :src="item.songData.cover" :alt="item.songData.name" class="cover-img" loading="lazy" />
              <span class="dt-chip diff-badge" :style="{ '--chip-color': item.diffData.color }">
                {{ item.diffKey }} Lv.{{ item.diffData.lvl }}
              </span>
            </div>
            <div class="card-info">
              <div class="info-title">{{ item.diffData.charter }}</div>
              <div class="info-charter">{{ item.diffData.tcharter }}</div>
            </div>
            <!-- 曲名压在曲绘上方但文字完全透明，看不见，只给浏览器 Ctrl+F 搜索定位 -->
            <span class="dt-cover-name">{{ item.songData.name }}</span>
          </div>
        </div>
      </section>
    </div>
  </div>
</template>

<script setup>
import { useOpenSong } from '../../api/openSong.js'
const openSong = useOpenSong()
import { computed, onMounted, onUnmounted, ref, defineProps, watch } from 'vue';
import { getCharterGroups } from '../../api/charters.js';
import { setAnchorNav, clearAnchorNav } from '../../composables/useAnchorNav.js';

const charterList = ref(null)

onMounted(async () => {
  try {
    const charterData = await getCharterGroups('/files/infos/charters.json')
    charterList.value = charterData
  } catch (error) {
    console.error('谱师列表加载失败：', error)
  }
})

const props = defineProps({
  columns: {
    type: Number,
    default: 2
  },
  gap: {
    type: Number,
    default: 0.14
  },
})

const getGridStyle = () => {
  return {
    '--column-count': props.columns,
    '--gap-rem': `${props.gap}rem`
  }
}

const sortedCardList = computed(() => {
  if(!charterList.value) return []
  return Object.entries(charterList.value).map(([key, value]) => ({ key, value }));
});

// 每个谱师登记成一个锚点（id 用序号，谱师名可能含空格等不合法字符）
watch(
  sortedCardList,
  (list) => {
    if (!list.length) {
      clearAnchorNav()
      return
    }
    setAnchorNav(
      list.map((group, index) => ({
        id: `charter-${index}`,
        label: group.key,
        icon: 'account-edit-outline'
      }))
    )
  },
  { immediate: true }
)

onUnmounted(clearAnchorNav)

const getGroupSortedCards = (songList) => {
  const items = []
  Object.entries(songList).forEach(([songKey, songData]) => {
    const { name, cover, ...difficulties } = songData
    Object.entries(difficulties).forEach(([diffKey, diffData]) => {
      items.push({ songKey, songData, diffKey, diffData })
    })
  })
  return items.sort((a, b) => {
    const qa = String(a.diffData.lvl).includes("?")
    const qb = String(b.diffData.lvl).includes("?")
    if (qa && !qb) return -1
    if (!qa && qb) return 1
    const na = Number(a.diffData.lvl) || 0
    const nb = Number(b.diffData.lvl) || 0
    return nb - na
  })
}
</script>

