/**
 * 谱师列表取数（/files/infos/charters.json）。
 * 数据结构是「谱师 → 曲目键名 → 歌曲」。
 */
import { loadJson } from './jsonCache.js'
import { decorateGroupedSongMap } from './common.js'

export async function getCharterGroups(jsonPath) {
  try {
    const jsonData = await loadJson(jsonPath)
    return decorateGroupedSongMap(jsonData, ['EZ', 'HD', 'IN', 'AT', 'LY', 'SP'])
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('请求路径：', jsonPath)
    return {}
  }
}
